using APItests.Models;

namespace APItests.Services;

// A deterministic demo bank, deliberately separated from a future AI provider.
public sealed class DemoQuestionGenerator
{
    public Question[] Generate(string topic, string department, string difficulty, int count, string context)
    {
        if (string.IsNullOrWhiteSpace(topic)) throw new ArgumentException("Укажите тему теста.");
        if (count is < 3 or > 8) throw new ArgumentException("Доступно от 3 до 8 демонстрационных вопросов.");
        var source = topic + " " + context;
        var security = new[] { "безопас", "фишинг", "парол", "данных", "кибер" }.Any(t => source.Contains(t, StringComparison.OrdinalIgnoreCase));
        var sales = new[] { "продаж", "клиент", "переговор", "возражен", "сервис" }.Any(t => source.Contains(t, StringComparison.OrdinalIgnoreCase));
        Question Q(string text, string correct, string b, string c, string d, string explanation)
            => new(text, [correct, b, c, d], 0, explanation);
        Question[] bank = security ? [
            Q("Вы получили письмо с просьбой срочно подтвердить пароль. Что нужно сделать?", "Проверить отправителя и сообщить в службу безопасности", "Перейти по ссылке из письма", "Переслать письмо коллегам", "Ответить отправителю с паролем", "Срочность и запрос пароля — признаки фишинга. Проверяйте запрос через независимый канал."),
            Q("Как безопасно передать клиенту файл с персональными данными?", "Через одобренный защищённый канал с ограниченным доступом", "Через личную почту", "По общедоступной ссылке", "Через любой мессенджер", "Доступ к персональным данным получают только уполномоченные получатели."),
            Q("Какой способ защиты рабочего аккаунта надёжнее?", "Уникальный пароль и многофакторная аутентификация", "Один сложный пароль для всех сервисов", "Пароль из названия компании", "Запись пароля на рабочем столе", "Многофакторная аутентификация добавляет защиту даже при утечке пароля."),
            Q("На рабочем компьютере обнаружен подозрительный файл. Ваши действия?", "Не открывать файл и обратиться в ИТ-службу", "Запустить файл для проверки", "Отправить файл знакомому", "Загрузить его в публичное облако", "Самостоятельный запуск может привести к заражению. Следуйте процедуре реагирования."),
            Q("Коллега просит ваш доступ к системе на один день. Как поступить?", "Помочь оформить персональный доступ через ответственного", "Сообщить свой пароль", "Войти за коллегу и уйти", "Отключить проверку входа", "Персональные учётные записи обеспечивают контроль прав и действий."),
            Q("Вы отправили конфиденциальный документ не тому адресату. Что делать первым?", "Немедленно сообщить об инциденте по установленному каналу", "Подождать ответа получателя", "Удалить письмо только у себя", "Ничего, если адресат знакомый", "Своевременное сообщение позволяет ограничить последствия утечки."),
            Q("Какие права доступа следует запрашивать для новой задачи?", "Только необходимые для выполнения задачи", "Права администратора на всякий случай", "Все права коллеги", "Доступ ко всем отделам", "Принцип минимальных привилегий снижает риски ошибочных и вредоносных действий."),
            Q("Что нужно сделать, отходя от рабочего компьютера?", "Заблокировать экран", "Свернуть рабочие окна", "Оставить записку", "Выключить только монитор", "Блокировка экрана предотвращает использование открытой сессии посторонними.")
        ] : sales ? [
            Q("С чего лучше начать разговор с новым клиентом?", "Выяснить его задачу и ожидаемый результат", "Сразу перечислить все функции", "Предложить максимальную скидку", "Обсудить недостатки конкурентов", "Выявление потребностей помогает предложить релевантное решение."),
            Q("Клиент говорит: «Это слишком дорого». Как ответить?", "Уточнить, с чем он сравнивает цену и что для него важно", "Сразу снизить цену вдвое", "Доказывать, что клиент ошибается", "Завершить разговор", "Уточнение помогает отличить бюджетное ограничение от непонимания ценности."),
            Q("Как убедиться, что вы правильно поняли потребность клиента?", "Кратко пересказать задачу и попросить подтверждение", "Не задавать уточняющих вопросов", "Отправить стандартную презентацию", "Сразу оформить заказ", "Подтверждение договорённостей снижает риск неверных ожиданий."),
            Q("Клиенту нужна функция, которой пока нет. Что делать?", "Честно описать ограничения и обсудить доступные варианты", "Пообещать, что она скоро появится", "Сказать, что она уже работает", "Сменить тему разговора", "Прозрачное обсуждение ограничений сохраняет доверие клиента."),
            Q("Как правильно завершить встречу с клиентом?", "Согласовать следующий шаг, ответственного и срок", "Сказать «Мы свяжемся» без даты", "Ждать инициативы клиента", "Повторить всю презентацию", "Конкретный следующий шаг помогает обеим сторонам двигаться к решению."),
            Q("Клиент сообщает о проблеме с продуктом. Что важно сделать сначала?", "Выслушать, уточнить ситуацию и зафиксировать обращение", "Объяснить, что другие не жалуются", "Предложить купить другой тариф", "Перевести разговор на новую продажу", "Сначала нужно понять проблему, чтобы выбрать корректный способ её решения."),
            Q("Какое описание предложения наиболее полезно для клиента?", "Как решение поможет достичь его конкретной цели", "Как давно работает компания", "Список всех технических терминов", "Количество слайдов в презентации", "Связь предложения с задачей клиента делает ценность понятной."),
            Q("Что следует зафиксировать в CRM после разговора?", "Потребности, договорённости и следующий контакт", "Только имя клиента", "Субъективное впечатление без фактов", "Ничего до заключения сделки", "Полная история взаимодействия помогает команде соблюдать договорённости.")
        ] : [
            Q($"Вы приступаете к задаче по теме «{topic.Trim()}». С чего начать?", "Уточнить цель, критерии результата и ответственного", "Сразу действовать по памяти", "Дождаться напоминания", "Передать задачу без пояснений", "Понятные критерии результата помогают выполнить задачу без лишних переделок."),
            Q("Вы заметили, что инструкция противоречит текущему процессу. Как поступить?", "Уточнить актуальный порядок у владельца процесса", "Игнорировать обе инструкции", "Выбрать более удобный вариант молча", "Изменить инструкцию без согласования", "Владелец процесса помогает определить актуальные требования."),
            Q("Какая формулировка задачи наиболее понятна исполнителю?", "Конкретный результат, срок и критерии приёмки", "Сделать как можно лучше", "Разобраться при наличии времени", "Повторить за коллегами", "Измеримые условия помогают одинаково понимать результат работы."),
            Q("Вы понимаете, что не успеваете завершить задачу в срок. Что делать?", "Заранее сообщить о риске и предложить варианты решения", "Скрыть задержку до дедлайна", "Снизить качество без согласования", "Отменить задачу самостоятельно", "Раннее сообщение о риске оставляет время на изменение плана."),
            Q("Как проверить, что обучение помогло сотруднику?", "Дать практическую задачу и оценить её по критериям", "Посчитать время на странице", "Проверить только факт присутствия", "Спросить, понравился ли дизайн", "Практическое применение показывает, сформирован ли необходимый навык."),
            Q("Коллега допустил ошибку в общей задаче. Как дать обратную связь?", "Обсудить конкретное действие, последствия и способ исправления", "Критиковать личные качества", "Обсудить ошибку со всеми, кроме коллеги", "Не объяснять причину замечания", "Обратная связь о действиях помогает исправить ситуацию и сохранить сотрудничество."),
            Q("Как правильно передать незавершённую задачу другому сотруднику?", "Описать статус, материалы, риски и следующий шаг", "Отправить только название задачи", "Удалить предыдущую переписку", "Попросить разобраться самостоятельно", "Контекст позволяет продолжить работу без потери важных деталей."),
            Q("После завершения проекта команда повторяет прежние ошибки. Что поможет?", "Разобрать причины и зафиксировать изменения процесса", "Назначить виновного без обсуждения", "Добавить больше отчётов без цели", "Начать следующий проект без анализа", "Разбор причин и конкретные изменения помогают закрепить полученный опыт.")
        ];
        return bank.Take(count).Select((q, i) =>
        {
            var shift = i % q.Options.Length;
            var options = Enumerable.Range(0, q.Options.Length).Select(j => q.Options[(j - shift + q.Options.Length) % q.Options.Length]).ToArray();
            return q with { Options = options, CorrectIndex = shift };
        }).ToArray();
    }
}
